delete from public.note_tags            where user_id = '11111111-1111-1111-1111-111111111111';
delete from public.note_folders         where user_id = '11111111-1111-1111-1111-111111111111';

delete from public.email_attachments    where email_id    in (select id from public.emails      where user_id = '11111111-1111-1111-1111-111111111111');
