insert into public.emails (id, email_account_id, user_id, folder_id, message_id, uid, from_address, to_addresses, cc_addresses, subject, preview_text, body_html, body_text, has_attachments, is_read, is_starred, received_at) values
  ('59000000-0000-0000-0000-000000000001', '57000000-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', '58000000-0000-0000-0000-000000000001', '<msg-001@easywork.app>', 1, 'product@easywork.app', ARRAY['demo.mail@easywork.app'], ARRAY[]::text[], 'EasyWork Q3 产品规划会纪要', '会议确定了 Q3 重点：记账报表、邮件收发、离线优先。', '<html><body><p>各位好，</p><p>今日产品规划会确定 Q3 重点方向：</p><ul><li>记账模块增加趋势报表与 CSV 导出</li><li>邮件接入真实 IMAP/SMTP</li><li>离线优先与本地缓存</li></ul><p>请各负责人下周提交详细排期。</p></body></html>', '各位好， 今日产品规划会确定 Q3 重点方向： - 记账模块增加趋势报表与 CSV 导出 - 邮件接入真实 IMAP/SMTP - 离线优先与本地缓存 请各负责人下周提交详细排期。', false, false, true,  '2026-08-10T09:00:00+08:00'),
  ('59000000-0000-0000-0000-000000000002', '57000000-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', '58000000-0000-0000-0000-000000000001', '<msg-002@easywork.app>', 2, 'finance@example.com',      ARRAY['demo.mail@easywork.app'], ARRAY[]::text[], '8 月信用卡账单已出', '本期应还 3,250.00 元，还款日为 8 月 25 日。', '<html><body><p>您好，</p><p>您的 8 月信用卡账单已生成，本期应还 <strong>3,250.00 元</strong>，还款日 8 月 25 日。</p><p>如有疑问请联系客服。</p></body></html>', '您好， 您的 8 月信用卡账单已生成，本期应还 3,250.00 元，还款日 8 月 25 日。 如有疑问请联系客服。', false, false, false, '2026-08-09T18:30:00+08:00'),
  ('59000000-0000-0000-0000-000000000003', '57000000-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', '58000000-0000-0000-0000-000000000001', '<msg-003@easywork.app>', 3, 'hr@company.com',           ARRAY['demo.mail@easywork.app'], ARRAY[]::text[], '入职资料补充通知', '请补充学历证明与身份证复印件。', '<html><body><p>您好，</p><p>入职流程中缺少以下资料，请于本周五前补充：</p><ol><li>学历证明扫描件</li><li>身份证复印件</li><li>体检报告</li></ol><p>谢谢配合。</p></body></html>', '您好， 入职流程中缺少以下资料，请于本周五前补充： 1. 学历证明扫描件 2. 身份证复印件 3. 体检报告 谢谢配合。', true,  true,  false, '2026-08-08T10:15:00+08:00'),
  ('59000000-0000-0000-0000-000000000004', '57000000-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', '58000000-0000-0000-0000-000000000001', '<msg-004@easywork.app>', 4, 'team@easywork.app',        ARRAY['demo.mail@easywork.app'], ARRAY[]::text[], '本周五代码评审安排', '周五 15:00 进行记账模块代码评审。', '<html><body><p>Hi，</p><p>本周五 15:00 进行记账模块代码评审，请大家提前拉取最新分支并准备提问。</p></body></html>', 'Hi， 本周五 15:00 进行记账模块代码评审，请大家提前拉取最新分支并准备提问。', false, true,  false, '2026-08-07T14:00:00+08:00'),
  ('59000000-0000-0000-0000-000000000005', '57000000-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', '58000000-0000-0000-0000-000000000002', '<msg-005@easywork.app>', 1, 'demo.mail@easywork.app',   ARRAY['product@easywork.app'],    ARRAY[]::text[], 'Re: EasyWork Q3 产品规划会纪要', '收到，我会先整理记账报表的需求文档。', '<html><body><p>收到，</p><p>我会先整理记账报表的需求文档，周二前同步。</p></body></html>', '收到， 我会先整理记账报表的需求文档，周二前同步。', false, true,  false, '2026-08-10T09:30:00+08:00'),
  ('59000000-0000-0000-0000-000000000006', '57000000-0000-0000-0000-000000000001', '11111111-1111-1111-1111-111111111111', '58000000-0000-0000-0000-000000000003', '<msg-006@easywork.app>', 1, 'noreply@service.com',      ARRAY['demo.mail@easywork.app'], ARRAY[]::text[], '服务订阅续费提醒', '您的订阅将于 3 天后到期。', '<html><body><p>您的订阅将于 3 天后到期，如需继续使用请前往账户设置续费。</p></body></html>', '您的订阅将于 3 天后到期，如需继续使用请前往账户设置续费。', false, true,  false, '2026-08-01T08:00:00+08:00');
